def cache_bill(requests, hit_price, miss_price, out_price):
    seen = set()
    hit = miss = out = 0
    for req in requests:
        prefix = req.get("prefix", "")
        size = max(1, len(prefix) // 4) if prefix else 0
        if size:
            if prefix in seen:
                hit += size
            else:
                miss += size
                seen.add(prefix)
        miss += req["tail_tokens"]
        out += req["out_tokens"]
    usd = (hit * hit_price + miss * miss_price + out * out_price) / 1e6
    return {"hit_tokens": hit, "miss_tokens": miss, "out_tokens": out, "usd": usd}
